(function(){'use strict';const $=id=>document.getElementById(id),C=window.FrontierCore;let game,view,raf,last=0,noticeLeft=0,hitLeft=0,hudTimer=0,terminalTab='upgrade',previousMode='',fault=false,audio=null,sound=true,sensitivity=1,aiming=false;let touch=matchMedia('(pointer:coarse)').matches||navigator.maxTouchPoints>0||window.innerWidth<=900;let screenMode='landscape';let viewport={width:800,height:600,rotation:0};window.FrontierViewport=viewport;let menuScrolls=[],layoutWidth=0,layoutHeight=0;let fireId=null,fireLook={x:0,y:0},drag=null;let keys=new Set(),fire=false,stick={x:0,z:0,id:null},look={id:null,x:0,y:0},stickKnob=document.querySelector('#stick i');document.body.classList.toggle('touch',touch);const drawMap=$('map').getContext('2d');
function orientDelta(dx,dy){return viewport.rotation===90?{x:dy,y:-dx}:viewport.rotation===-90?{x:-dy,y:dx}:{x:dx,y:dy}}
function applyLayout(){let w=window.innerWidth||800,h=window.innerHeight||600;layoutWidth=w;layoutHeight=h;viewport.rotation=screenMode==='landscape'&&h>w?90:screenMode==='portrait'&&w>h?-90:0;viewport.width=viewport.rotation?h:w;viewport.height=viewport.rotation?w:h;let shell=$('game-shell');shell.style.width=viewport.width+'px';shell.style.height=viewport.height+'px';shell.style.transform=viewport.rotation===90?'translate('+w+'px,0) rotate(90deg)':viewport.rotation===-90?'translate(0,'+h+'px) rotate(-90deg)':'none';document.body.classList.toggle('layout-portrait',viewport.width<viewport.height);document.body.classList.toggle('layout-compact',viewport.height<=580);document.body.classList.toggle('rotated-cw',viewport.rotation===90);document.body.classList.toggle('rotated-ccw',viewport.rotation===-90);document.querySelectorAll('[data-screen]').forEach(b=>{let selected=b.dataset.screen===screenMode;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected?'true':'false')});}
function error(err){fault=true;if(raf)cancelAnimationFrame(raf);$('hud').hidden=true;$('overlay').hidden=false;for(let id of ['start-panel','pause-panel','terminal-panel','end-panel'])$(id).hidden=true;$('error-panel').hidden=false;$('error-message').textContent='请使用最新版小红书或支持 WebGL 的手机浏览器。'+((err&&err.message)?'（'+err.message+'）':'')}
function init(){try{fault=false;applyLayout();game=new C.Game();if(view)view.dispose();view=new window.FrontierView($('battle'),game);last=performance.now();previousMode='';syncMode();raf=requestAnimationFrame(frame)}catch(e){error(e)}}
function stopMenus(){menuScrolls.forEach(scroll=>scroll.stop());}
function clearInput(){stopMenus();keys.clear();fire=false;drag=null;fireId=null;stick.x=stick.z=0;stick.id=null;look.id=null;stickKnob.style.transform='';}
function doPause(){if(['assault','intermission'].includes(game.phase)){game.terminal=false;game.paused=true;clearInput();syncMode()}}
function resume(){startAudio();game.paused=false;game.terminal=false;clearInput();syncMode()}
function interact(){game.interact();clearInput();syncMode()}
function tone(freq,duration=.06,volume=.028,type='triangle'){if(!sound||!audio)return;try{let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.45,audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch(e){}}
function startAudio(){try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();audio.resume()}catch(e){}}
function syncMode(){let mode=game.phase==='briefing'?'start':game.phase==='victory'||game.phase==='defeat'?'end':game.terminal?'terminal':game.paused?'pause':'play';if(mode===previousMode)return;stopMenus();previousMode=mode;$('hud').hidden=mode==='start'||mode==='end';$('overlay').hidden=mode==='play';document.body.classList.toggle('briefing',mode!=='play');for(let m of ['start','pause','terminal','end','error'])$(m+'-panel').hidden=m!==mode;if(mode==='terminal')renderTerminal();if(mode==='end'){$('end-title').textContent=game.phase==='victory'?'防线坚守成功':'指挥中心失守';$('end-stats').textContent='守到第 '+game.wave+' 波 · 击杀 '+game.kills+' · 先锋阵亡 '+game.deaths+' 次 · 摧毁传送门 '+game.enemyBases.filter(b=>!b.portal.alive).length+'/6 · 战斗 '+Math.floor(game.time/60)+' 分 '+Math.floor(game.time%60)+' 秒'}if(mode!=='play'){clearInput();$('squad-orders').hidden=true}}
function tickInput(dt){let p=game.player,x=stick.x+(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0),z=stick.z+(keys.has('KeyW')?1:0)-(keys.has('KeyS')?1:0);if(keys.has('ArrowLeft'))p.yaw-=dt*1.8;if(keys.has('ArrowRight'))p.yaw+=dt*1.8;return{x,z,yaw:p.yaw,pitch:p.pitch,fire:fire||keys.has('Space'),sprint:keys.has('ShiftLeft')&&!aiming,aim:aiming,aimPoint:view.aim(touch,aiming)}}
function frame(now){try{let elapsed=(now-last)/1000;let dt=Math.min(.05,elapsed);last=now;if(view.observe)view.observe(elapsed);game.tick(dt,tickInput(dt));let ev=game.events.splice(0);for(let event of ev){view.effect(event);if(event.type==='notice'){$('notice').textContent=event.text;noticeLeft=4.5}if(event.type==='shot'&&event.color==='player')tone(180,.045,.035,'sawtooth');if(event.type==='shot'&&event.color==='tank')tone(65,.15,.05,'triangle');if(event.type==='hit'&&event.player){hitLeft=.14;tone(750,.03,.015)}if(event.type==='death'&&event.enemy)tone(90,.1,.025)}noticeLeft-=dt;hitLeft-=dt;$('notice').classList.toggle('show',noticeLeft>0);$('hitmarker').hidden=hitLeft<=0;$('damage-flash').style.opacity=game.player.alive&&game.time-game.player.lastDamage<.22?.35:0;syncMode();view.update(dt,aiming);hudTimer-=dt;if(hudTimer<=0){hudTimer=.12;updateHUD()}raf=requestAnimationFrame(frame)}catch(err){console.error(err);error(err)}}
function updateHUD(){let p=game.player;$('base-hp').textContent=Math.ceil(game.command.hp)+' / '+game.command.max;$('base-meter').style.width=game.command.hp/game.command.max*100+'%';$('wave').textContent='第 '+Math.max(1,game.wave)+' / 5 波';let pending=game.spawnQueue.length+game.batches.filter(b=>!b.done).reduce((s,b)=>s+b.units.length,0);$('wave-detail').textContent=game.phase==='intermission'?'自由整备 · '+Math.ceil(game.intermission)+' 秒':'场上 '+game.enemies.length+' · 待抵达 '+pending;$('credits').textContent=game.credits;$('squad-count').textContent=game.squad.length+'/4';$('kills').textContent=game.kills;$('player-hp').textContent=Math.ceil(p.hp);$('player-meter').style.width=p.hp/p.max*100+'%';$('ammo').textContent=p.alive?(p.reload>0?'换弹 '+p.reload.toFixed(1)+'s':p.ammo+' / 30'):'重生 '+Math.ceil(p.respawn)+'s';$('context').textContent=game.context();$('interact').textContent=p.bunker?'离堡':game.nearCommand?'整备':game.recruitTarget()?'招募':'交互';let tank=game.tank,factory=game.sites.find(s=>s.id==='factory');$('tank-status').textContent=tank?'坦克 '+Math.ceil(tank.hp)+' / '+tank.max:game.ready('factory')?'坦克生产 '+Math.ceil(game.tankTimer)+'秒':factory.state==='building'?'工厂施工 '+Math.ceil(factory.left)+'秒':'工厂未投产';let support=game.support;$('operations-status').textContent='守卫 '+game.marines.length+'/'+game.capacity+' · 集结 '+support.rallyCount+'/6 · 出征 '+support.attackingCount+'\n维修工 '+support.workers.length+'/2 · 敌军传送门 '+game.enemyBases.filter(b=>b.portal.alive).length+'/6';miniMap()}
function miniMap(){let ctx=drawMap,w=144,m=C.MAP,scale=Math.min((w-10)/(m.maxX-m.minX),(w-10)/(m.maxZ-m.minZ));ctx.fillStyle='#28404b';ctx.fillRect(0,0,w,w);const pt=e=>({x:w/2+(e.x-(m.minX+m.maxX)/2)*scale,y:w/2+((m.minZ+m.maxZ)/2-e.z)*scale});ctx.fillStyle='#738587';let left=pt({x:-26,z:26}),right=pt({x:26,z:-22});ctx.fillRect(left.x,left.y,right.x-left.x,right.y-left.y);ctx.fillStyle='#182d35';for(let b of C.OBSTACLES){let p=pt({x:b.x-b.xs/2,z:b.z+b.zs/2});ctx.fillRect(p.x,p.y,b.xs*scale,b.zs*scale)}for(let e of game.entities){if(!e.alive)continue;let p=pt(e);ctx.fillStyle=e.enemy?(e.role==='portal'?'#ed53d1':'#ff7388'):e===game.player?'#ffffff':e.role==='worker'?'#ffe071':e.role==='assault'?'#89eda6':e.squad?'#ffbc59':'#5ce7ed';let size=e.role==='portal'?7:game.building(e)?4:e.role==='tank'?4:e===game.player?4:2;ctx.fillRect(p.x-size/2,p.y-size/2,size,size)}let p=pt(game.player);ctx.strokeStyle='#fff';ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+Math.sin(game.player.yaw)*9,p.y-Math.cos(game.player.yaw)*9);ctx.stroke()}

function card(title,description,state,label,action,disabled=false){let box=document.createElement('article');box.className='upgrade-card';let h=document.createElement('h3');h.textContent=title;let text=document.createElement('p');text.textContent=description;let status=document.createElement('span');status.className='state';status.textContent=state;let btn=document.createElement('button');btn.textContent=label;btn.disabled=disabled;btn.addEventListener('click',()=>{if(game.buy(action)){tone(520,.1,.045);renderTerminal()}else {let e=game.events.slice().reverse().find(e=>e.type==='notice');if(e)status.textContent=e.text;else status.textContent='当前条件不满足'}});box.append(h,text,status,btn);$('terminal-content').append(box)}
function fortifyCard(id,title){const g=game,info=g.support.fortifyInfo(id),e=info.entity;card(title+' · 结构加固','最大耐久 +'+info.delta+'，同时恢复 '+info.delta+'；重建继承。日常维修由工人自动进行。','等级 '+info.level+' / '+info.maxLevel+(e&&e.alive?' · 耐久 '+Math.ceil(e.hp)+' / '+e.max:''),info.level>=info.maxLevel?'已达上限':info.cost+' 补给 · 加固','fortify:'+id,!info.available||g.credits<info.cost)}
function renderTerminal(){let g=game;$('terminal-content').textContent='';$('terminal-credits').textContent='可用补给 '+g.credits;$('next-wave').hidden=g.phase!=='intermission';document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===terminalTab));
 if(terminalTab==='upgrade'){
  for(let row of [['weapon','强化磁轨步枪','每发伤害 +6',90,80,4],['defense','协同火力','守卫、进攻部队和小队伤害 +3，地堡伤害 +4',110,90,4],['production','兵营补员','全体兵营守卫补员间隔减少 2 秒；进攻编制独立补员',200,120,2],['armor','地堡装甲','全体地堡耐久上限 +400，同时恢复 400',180,120,2],['firepower','地堡火力','全体地堡自动炮伤害 +5',220,140,2]]){let [key,title,desc,base,step,max]=row,cost=base+step*g[key],full=g[key]>=max;card(title,desc,'等级 '+g[key]+' / '+max,full?'已达上限':cost+' 补给 · 升级',key,full||g.credits<cost)}
  fortifyCard('command','指挥中心');
 }else if(terminalTab==='build'){
  for(let site of g.sites){if(site.state==='ready'){fortifyCard(site.id,site.name);continue}let building=site.state==='building';card(site.name,site.role==='factory'?'28 秒施工，投产后 24 秒自动生产坦克':site.id==='reserve'?'22 秒施工，驻军上限增至 12，进攻补员加快至每 6 秒一人，解锁科技':site.role==='bunker'?'18 秒施工，驻守入口外侧，与中央防线交叉开火':'22 秒施工，分别补充守卫和进攻部队',building?'施工中 · '+Math.ceil(site.left)+' 秒':site.state==='destroyed'?'已失守，重建保留加固等级':'尚未建造',building?'返回战场继续施工':site.cost+' 补给 · '+(site.state==='destroyed'?'重建':'建造'),'build:'+site.id,building||g.credits<site.cost)}
  let titles=['步兵复合装甲','穿甲弹药','精英雇佣兵训练'],desc=['全体战斗步兵受伤降低 15% · 16 秒','对重甲与攻城敌人的护甲减伤降至 10% · 20 秒','雇佣兵耐久 +80、伤害 +6 · 22 秒'];
  for(let i=0;i<3;i++){let cost=[240,280,300][i];card(titles[i],desc[i],g.tech[i]?'已完成':(g.research&&g.research.id===i)?'研究中 '+Math.ceil(g.research.left)+' 秒':!g.ready('reserve')?'需要已投产的增援兵营':g.research?'等待当前研究完成':'可以研究',cost+' 补给 · 研究','tech:'+i,g.tech[i]||!!g.research||!g.ready('reserve')||g.credits<cost)}
 }else{
  card('自动进攻部队','6 人实际到达集结区后自动出征，攻击仍存活的传送门据点。独立于守卫和先锋小队，上限 24 人。','集结 '+g.support.rallyCount+'/6 · 出征 '+g.support.attackingCount,'兵营自动补员','none',true);
  card('基地维修组','2 名工人巡回缓慢修理基地内建筑与机械单位。每人每秒恢复 6 耐久，阵亡后 20 秒补员。','工人 '+g.support.workers.length+'/2','自动维修 · 无需补给','none',true);
  for(let i=0;i<2;i++){let unit=g.squad.find(e=>e.role==='merc'&&e.contract===i),hired=g.contracts[i];card(i?'精英 · 岩盾':'精英 · 猎隼','永久合同（本局） · 阵亡后 12 秒免费复活',unit?'耐久 '+Math.ceil(unit.hp)+' / '+unit.max:hired?'复活中 '+Math.ceil(g.mercTimers[i])+' 秒':'合同尚未签署',hired?'已签约':'120 补给 · 签约','hire',hired||g.credits<120)}
  for(let i=0;i<2;i++){let unit=g.squad.filter(e=>e.role==='marine')[i];card('随行守卫 '+(i+1),'在战场面向 4 米内守卫，点击交互免费招募。阵亡后需重新招募。',unit?'耐久 '+Math.ceil(unit.hp)+' / '+unit.max:'空位','前往战场招募','none',true)}
 }
}

function restart(){if(raf)cancelAnimationFrame(raf);clearInput();aiming=false;$('aim').classList.remove('selected');init();game.start();startAudio();syncMode()}
$('start').addEventListener('click',()=>{startAudio();game.start();syncMode()});$('pause').addEventListener('click',doPause);$('resume').addEventListener('click',resume);$('close-terminal').addEventListener('click',resume);$('restart').addEventListener('click',restart);$('again').addEventListener('click',restart);$('retry').addEventListener('click',()=>location.reload());$('next-wave').addEventListener('click',()=>{if(game.phase==='intermission'){game.nextWave();syncMode()}});$('sensitivity').addEventListener('input',e=>sensitivity=+e.target.value);$('sound').addEventListener('change',e=>sound=e.target.checked);document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{terminalTab=b.dataset.tab;renderTerminal()}));$('interact').addEventListener('click',interact);$('reload').addEventListener('click',()=>game.reload());$('aim').addEventListener('click',()=>{aiming=!aiming;$('aim').classList.toggle('selected',aiming)});$('squad-menu').addEventListener('click',()=>{$('squad-orders').hidden=!$('squad-orders').hidden});document.querySelectorAll('[data-order]').forEach(b=>b.addEventListener('click',()=>{game.giveOrder(b.dataset.order);$('squad-orders').hidden=true}));
function pointer(el,onDown,onMove,onUp){el.addEventListener('pointerdown',e=>{e.preventDefault();if(!game.active)return;el.setPointerCapture(e.pointerId);onDown(e)});el.addEventListener('pointermove',e=>onMove&&onMove(e));const up=e=>{onUp(e);if(el.hasPointerCapture(e.pointerId))el.releasePointerCapture(e.pointerId)};el.addEventListener('pointerup',up);el.addEventListener('pointercancel',up);el.addEventListener('lostpointercapture',e=>{if(e.target===el)onUp(e)})}
function updateStick(e){let r=$('stick').getBoundingClientRect(),delta=orientDelta(e.clientX-(r.left+r.width/2),e.clientY-(r.top+r.height/2)),dx=delta.x,dy=delta.y,n=Math.max(1,Math.hypot(dx,dy)/43);stick.x=dx/n/43;stick.z=-dy/n/43;stickKnob.style.transform='translate('+(dx/n)+'px,'+(dy/n)+'px)'}
pointer($('stick-zone'),e=>{if(stick.id!==null)return;stick.id=e.pointerId;updateStick(e)},e=>{if(e.pointerId===stick.id)updateStick(e)},e=>{if(e.pointerId!==stick.id)return;stick.id=null;stick.x=stick.z=0;stickKnob.style.transform='' });
// Aim dragging uses the same logical screen axes on the view and fire controls.
function turnWithTouch(e,origin){let delta=orientDelta(e.clientX-origin.x,e.clientY-origin.y);game.player.yaw+=delta.x*.006*sensitivity;game.player.pitch=C.clamp(game.player.pitch+delta.y*.005*sensitivity,-.55,1.05);origin.x=e.clientX;origin.y=e.clientY;}
pointer($('look-zone'),e=>{if(look.id!==null)return;look.id=e.pointerId;look.x=e.clientX;look.y=e.clientY},e=>{if(e.pointerId===look.id&&game.active)turnWithTouch(e,look)},e=>{if(e.pointerId===look.id)look.id=null});
// Keep a separate pointer origin so moving, firing and a second aim finger coexist.
pointer($('fire'),e=>{if(fireId!==null)return;fireId=e.pointerId;fireLook.x=e.clientX;fireLook.y=e.clientY;fire=true},e=>{if(e.pointerId===fireId&&game.active)turnWithTouch(e,fireLook)},e=>{if(e.pointerId===fireId){fire=false;fireId=null}});
pointer($('battle'),e=>{if(touch)return;if(e.button===2){aiming=true;return}if(e.button===0){fire=true;drag={id:e.pointerId,x:e.clientX,y:e.clientY}}},e=>{if(!drag||e.pointerId!==drag.id||!game.active)return;let delta=orientDelta(e.clientX-drag.x,e.clientY-drag.y);game.player.yaw+=delta.x*.004*sensitivity;game.player.pitch=C.clamp(game.player.pitch+delta.y*.004*sensitivity,-.55,1.05);drag.x=e.clientX;drag.y=e.clientY},e=>{if(e.button===2)aiming=false;if((drag&&drag.id===e.pointerId)){drag=null;fire=false}});
document.addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement)return;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Escape'){game.paused||game.terminal?resume():doPause();return}if(e.repeat)return;if(e.code==='KeyE'){interact();return}if(!game.active)return;keys.add(e.code);if(e.code==='KeyR')game.reload();if(e.code==='KeyF')game.giveOrder('follow');if(e.code==='KeyG')game.giveOrder('hold');if(e.code==='KeyB')game.giveOrder('bunker')});document.addEventListener('keyup',e=>keys.delete(e.code));document.addEventListener('contextmenu',e=>e.preventDefault());window.addEventListener('blur',()=>{stopMenus();doPause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){stopMenus();doPause();if(raf)cancelAnimationFrame(raf);raf=null;if(audio&&audio.suspend)audio.suspend()}else if(!fault&&!raf){last=performance.now();raf=requestAnimationFrame(frame)}});document.querySelectorAll('[data-screen]').forEach(b=>b.addEventListener('click',()=>{screenMode=b.dataset.screen;clearInput();applyLayout();if(view)view.resize()}));window.addEventListener('resize',()=>{if((window.innerWidth||800)===layoutWidth&&(window.innerHeight||600)===layoutHeight)return;clearInput();applyLayout();touch=matchMedia('(pointer:coarse)').matches||navigator.maxTouchPoints>0||window.innerWidth<=900;document.body.classList.toggle('touch',touch);view&&view.resize()});$('battle').addEventListener('webglcontextlost',e=>{e.preventDefault();doPause();error(new Error('画面资源已释放，请重新加载。'))});$('battle').addEventListener('webglcontextrestored',()=>{if(fault)$('error-message').textContent='画面资源已恢复，请点重新加载开始新一局。'});window.addEventListener('error',e=>{if(e.message)error(new Error(e.message))});
menuScrolls=Array.from(document.querySelectorAll('.panel')).map(panel=>window.FrontierMenuScroll.create(panel,()=>viewport.rotation));
init();
})();
